    if (k < 0) return {};
    unordered_map<TreeNode*, TreeNode*> parentMap;
    unordered_set<TreeNode*> visited;
    TreeNode* targetNode = nullptr;
    initializeParentMap(root, nullptr, targetVal, parentMap, targetNode);

