class Solution:
    def shortestDistance(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dirs = ((0, 1), (0, -1), (1, 0), (-1, 0))
        res = float('inf')
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    res = min(res, self.bfs(i, j, grid, dirs))
        return res if res != float('inf') else -1

    def bfs(self, i, j, grid, dirs):
        m, n = len(grid), len(grid[0])
        q = [(i, j)]
        dist = 0
        while q:
            size = len(q)
            for _ in range(size):
                x, y = q.pop(0)
                for dx, dy in dirs:
                    i, j = x, y
                    while 0 <= i + dx < m and 0 <= j + dy < n and grid[i + dx][j + dy] > 0:
                        i += dx
                        j += dy
                    if grid[i][j] == -1:
                        grid[i][j] -= 1
                        q.append((i, j))
                        dist += abs(x - i) + abs(y - j)
            dist += 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] < 0:
                    return float('inf')
        return dist
