class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {
        // Create a dummy node to handle edge cases where the head node itself is part of a zero-sum sublist
        ListNode dummy(0);
        dummy.next = head;
        ListNode* current = &dummy;

        // Iterate through the linked list
        while (current) {
            int sum = 0;
            ListNode* temp = current->next;
            // Check for zero-sum sublists starting from the current node
            while (temp) {
                sum += temp->val;
                if (sum == 0) {
                    // If a zero-sum sublist is found, remove it by updating the next pointer of the previous node
                    current->next = temp->next;
                }
                temp = temp->next;
            }
            // Move to the next node in the linked list
            current = current->next;
            if (current) {
                head = current->next;
            }
        }

        // Return the modified linked list
        return dummy.next;
    }
};
