class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        N = len(grid)
        graph = [[0] * (N + 1) * (N + 1) for _ in range(4)]

        def dfs(x, y, d):
            if x < 0 or x >= 4 * N or y < 0 or y >= 4 * N or graph[d][x][y] == 1:
                return

            graph[d][x][y] = 1

            dx = [0, 0, 1, -1]
            dy = [1, -1, 0, 0]

            for i in range(4):
                nx = x + dx[i]
                ny = y + dy[i]

                if 0 <= nx < 4 * N and 0 <= ny < 4 * N:
                    if graph[d][nx][ny] == 0:
                        dfs(nx, ny, d)
                    else:
                        if d == 0 and nx == 3 and ny == 0:
                            dfs(nx, ny, 1)
                        elif d == 0 and nx == 0 and ny == 3:
                            dfs(nx, ny, 2)
                        elif d == 1 and nx == 3 and ny == 0:
                            dfs(nx, ny, 0)
                        elif d == 1 and nx == 0 and ny == 3:
                            dfs(nx, ny, 3)
                        elif d == 2 and nx == 3 and ny == 0:
                            dfs(nx, ny, 3)
                        elif d == 2 and nx == 0 and ny == 3:
                            dfs(nx, ny, 0)
                        elif d == 3 and nx == 3 and ny == 0:
                            dfs(nx, ny, 2)
                        elif d == 3 and nx == 0 and ny == 3:
                            dfs(nx, ny, 1)

        for i in range(N):
            for j in range(N):
                if grid[i][j] == "/":
                    graph[0][i * 4 + 1][j * 4 + 3] = 1
                    graph[3][i * 4 + 3][j * 4 + 1] = 1
                elif grid[i][j] == "\\":
                    graph[0][i * 4 + 3][j * 4 + 1] = 1
                    graph[3][i * 4 + 1][j * 4 + 3] = 1

        answer = 0

        for i in range(4 * N):
            for j in range(4 * N):
                if graph[0][i][j] == 0:
                    dfs(i, j, 0)
