using namespace std;

class Solution {
public:
    bool canReach(vector<vector<int>>& grid, int row, int col) {
        if (row < 0 || col < 0 || row >= grid.size() || col >= grid[0].size() || grid[row][col] == 0) return false;

        if (row == grid.size() - 1 && col == grid[0].size() - 1) return true;

        grid[row][col] = 0;

        return canReach(grid, row + 1, col) || canReach(grid, row, col + 1);
    }

    bool canDisconnect(vector<vector<int>>& grid) {
        int reachableCount = 0;

        for (int row = 1; row < grid.size(); row++) {
            for (int col = 1; col < grid[0].size(); col++) {
                if (grid[row][col] == 1 && (canReach(grid, row - 1, col) || canReach(grid, row, col - 1))) {
                    reachableCount++;
                    if (reachableCount > 1) return true;
                }
            }
        }

        return reachableCount <= 1;
    }

    int reachableNodes(int n, vector<vector<int>>& edges, vector<int>& restricted) {
        vector<vector<int>> graph(n);
        for (const auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }

        vector<bool> visited(n, false);
        for (int node : restricted) {
            visited[node] = true;
        }

        queue<int> q;
        q.push(0);
        visited[0] = true;

        int reachableNodes = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            reachableNodes++;

            for (int neighbor : graph[node]) {
                if (!visited[neighbor]) {
                    q.push(neighbor);
                    visited[neighbor] = true;
                }
            }
        }

        return reachableNodes;
    }
