            land[sr][sc] = 0
            fill(sr - 1, sc)
            fill(sr + 1, sc)
            fill(sr, sc - 1)
            fill(sr, sc + 1)

        res = []
        for i in range(len(land)):
            for j in range(len(land[0])):
                if land[i][j] == 1:
                    res.append([i,j])
                    fill(i,j)
        return res
