class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        vector<vector<int>> g(3 * n, vector<int>(3 * n, 0));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == ' ') continue;
                if (grid[i][j] == '/') {
                    for (int k = 0; k < 3; k++) {
                        g[i * 3 + k][j * 3 + 2 - k] = 1;
                    }
                } else {
                    for (int k = 0; k < 3; k++) {
                        g[i * 3 + k][j * 3 + k] = 1;
                    }
                }
            }
        }

        function<void(int, int)> dfs = [&](int i, int j) {
            if (i < 0 || i >= 3 * n || j < 0 || j >= 3 * n || g[i][j]) return;
            g[i][j] = 1;
            dfs(i - 1, j);
            dfs(i + 1, j);
            dfs(i, j - 1);
            dfs(i, j + 1);
        };

        int res = 0;
        for (int i = 0; i < 3 * n; i++) {
            for (int j = 0; j < 3 * n; j++) {
                if (!g[i][j]) {
                    dfs(i, j);
                    res++;
                }
            }
        }
        return res;
    }
};
```

