class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        vector<vector<int>> g(3 * n, vector<int>(3 * n));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == ' ') continue;

                int r = i * 3, c = j * 3;

                if (grid[i][j] == '/') {
                    g[r][c + 2] = 1;
                    g[r + 1][c + 1] = 1;
                    g[r + 2][c] = 1;
                } else {
                    g[r][c] = 1;
                    g[r + 1][c + 1] = 1;
                    g[r + 2][c + 2] = 1;
                }
            }
        }

        int res = 0;

        for (int i = 0; i < 3 * n; i++) {
            for (int j = 0; j < 3 * n; j++) {
                if (g[i][j] == 0) {
                    dfs(g, i, j);
                    res++;
