public class Solution {
    public List<Integer> countSmaller(int[] nums) {
        List<Integer> res = new ArrayList<>();
        int n = nums.length;
        int[] indexes = new int[n]; // indexes of the elements in the original array
        int[] counts = new int[n]; // counts of smaller elements to the right
        for (int i = 0; i < n; ++i)
            indexes[i] = i;

        countWhileMergeSort(nums, indexes, counts, 0, n - 1);

        for (int i = 0; i < n; ++i)
            res.add(counts[i]);
        return res;
    }

    private void countWhileMergeSort(int[] nums, int[] indexes, int[] counts, int start, int end) {
        if (start >= end)
            return;

        int mid = start + (end - start) / 2;
        countWhileMergeSort(nums, indexes, counts, start, mid);
        countWhileMergeSort(nums, indexes, counts, mid + 1, end);

        // merge the two sorted arrays into a new sorted array
        int[] merged = new int[end - start + 1];
        int i = start, j = mid + 1, k = 0;
        while (i <= mid || j <= end) {
            if (i > mid)
                merged[k++] = indexes[j++];
            else if (j > end)
                merged[k++] = indexes[i++];
            else if (nums[indexes[i]] <= nums[indexes[j]])
                merged[k++] = indexes[i++];
            else {
                // there are (mid-i+1) smaller elements to the right of nums[indexes[i]]
                counts[indexes[i]] += end - j + 1;
                merged[k++] = indexes[j++];
            }
        }

        // copy the merged array back to the original array
        for (i = start, j = 0; i <= end; ++i, ++j)
            indexes[i] = merged[j];
    }
}
