#include <set>

class Solution {
public:
    int maximumWhiteTiles(std::vector<std::vector<int>>& tiles, int carpetLen) {
        std::multiset<int> s;
        for (auto& tile : tiles) {
            s.insert(tile[0]);
            s.insert(tile[1] + 1);
        }

        int res = 0, cur = 0;
        for (auto it = s.begin(); it != s.end(); ++it) {
            cur += *it - *std::prev(it);
            while (*it - *std::next(s.begin()) >= carpetLen) {
                cur -= *std::next(s.begin()) - *s.begin();
                s.erase(s.begin());
            }
            res = std::max(res, cur);
        }
        return res;
    }
};
