public int maxSumAfterPartitioning(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n + 1];

    for (int i = 1; i <= n; ++i) {
        int maxVal = 0;
        for (int j = 1; j <= Math.min(i, k); ++j) {
            maxVal = Math.max(maxVal, nums[i - j]);
