import java.util.PriorityQueue;

public boolean hasCycle(int[][] graph) {
    int n = graph.length;
    int[] inDegree = new int[n];

    // Calculate in-degrees of all vertices
    for (int i = 0; i < n; i++) {
        for (int neighbor : graph[i]) {
            inDegree[neighbor]++;
        }
    }

    // Initialize a priority queue with all vertices having zero in-degree
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    for (int i = 0; i < n; i++) {
        if (inDegree[i] == 0) {
            queue.offer(i);
        }
    }

    // Process each vertex in topological order
    while (!queue.isEmpty()) {
        int vertex = queue.poll();

        // Decrease in-degree of all neighbors
        for (int neighbor : graph[vertex]) {
            inDegree[neighbor]--;

            // If a neighbor has zero in-degree, add it to the queue
            if (inDegree[neighbor] == 0) {
                queue.offer(neighbor);
            }
        }
    }

    // Check if there are any remaining vertices with non-zero in-degree
    for (int i = 0; i < n; i++) {
        if (inDegree[i] != 0) {
            return true; // Cycle detected
        }
    }

    return false; // No cycle detected
}
