class Solution {
public:
    vector<vector<int>> buildMatrix(int k, vector<vector<int>>& rowConditions, vector<vector<int>>& colConditions) {
        vector<vector<int>> res(k, vector<int>(k));
        vector<int> row_order = topologicalSort(rowConditions, k);
        vector<int> col_order = topologicalSort(colConditions, k);
        if (row_order.empty() || col_order.empty()) return {};
        unordered_map<int, int> col_index;
        for (int i = 0; i < k; ++i) {
            col_index[col_order[i]] = i;
        }
        for (int i = 0; i < k; ++i) {
            res[i][col_index[row_order[i]]] = row_order[i];
        }
        return res;
    }

    vector<int> topologicalSort(vector<vector<int>>& conditions, int k) {
        vector<int> in_degree(k + 1, 0);
        vector<vector<int>> graph(k + 1);
        for (const auto& c : conditions) {
            graph[c[0]].push_back(c[1]);
            ++in_degree[c[1]];
        }
        queue<int> q;
        for (int i = 1; i <= k; ++i) {
            if (in_degree[i] == 0) q.push(i);
        }
        vector<int> order;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            order.push_back(node);
            for (int neighbor : graph[node]) {
                --in_degree[neighbor];
                if (in_degree[neighbor] == 0) q.push(neighbor);
            }
        }
        if (order.size() < k) return {};
        return order;
    }
};
