import java.util.*;

class Solution {
    public int minTime(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] visited = new int[m][n];

        for (int[] row : visited) {
            Arrays.fill(row, 1000000);
        }

        final int[] dx = {-1, 0, 1, 0};
        final int[] dy = {0, 1, 0, -1};

        visited[0][0] = 0;

        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{0, 0});

        while (!q.isEmpty()) {
            int x = q.peek()[0];
            int y = q.peek()[1];
            q.poll();

            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    int t = Math.max(grid[nx][ny], visited[x][y] + 1);
                    if (visited[nx][ny] > t) {
                        visited[nx][ny] = t;
                        q.add(new int[]{nx, ny});
                    }
                }
            }
        }

        return visited[m - 1][n - 1] == 1000000 ? -1 : visited[m - 1][n - 1];
    }
}
