using namespace std;

class Solution {
public:
    int numSubarraysWithSum(vector<int>& nums, int goal) {
        int mod = 1e9 + 7;
        int n = nums.size();
        vector<int> prefixSum(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = (prefixSum[i] + nums[i]) % mod;
        }

        int ans = 0;
        for (int i = 0; i <= n; i++) {
            int target = (prefixSum[i] - goal + mod) % mod;
            ans = (ans + countOccurrences(prefixSum, target, i)) % mod;
        }
        return ans;
    }

private:
    int countOccurrences(vector<int>& arr, int target, int endIndex) {
        int count = 0;
        stack<int> st;
        for (int i = 0; i <= endIndex; i++) {
            if (arr[i] == target) {
                count++;
            }
            while (!st.empty() && arr[st.top()] > arr[i]) {
                st.pop();
            }
            st.push(i);
        }
        return count;
    }
};
