    int n = barcodes.size();
    vector<int> count(10001, 0);
    for (int i = 0; i < n; ++i) {
        ++count[barcodes[i]];
    }

    auto comp = [](const pair<int, int>& a, const pair<int, int>& b) { return a.second < b.second; };
    priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(comp)> pq(comp);
    for (int i = 1; i <= 10000; ++i) {
        if (count[i] > 0) {
