    int idx = 0;
    while (!pq.empty()) {
        auto curr = pq.top();
        pq.pop();
        while (curr.second > 0) {
            barcodes[idx] = curr.first;
            curr.second--;
            idx += 2;
            if (idx >= n) {
                idx = 1;
            }
        }
    }
    return barcodes;
}
