                dfs(r, c - 1, r0, c0)

        def normalize(island):
            ret = []
            for p in island:
                x, y = p
                ret += [(x, y), (x, -y), (-x, y), (-x, -y), (y, x), (y, -x), (-y, x), (-y, -x)]
            ret.sort()
            return tuple(ret)

        distinctIslands = set()
