    int n = s.length();
    int[][] dp = new int[n][n];
    char[][] path = new char[n][n];

    for (int i = n - 1; i >= 0; i--) {
        dp[i][i] = 1;
        path[i][i] = s.charAt(i);
        for (int j = i + 1; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) {
                dp[i][j] = 2 + dp[i + 1][j - 1];
                path[i][j] = 'd';
            } else if (dp[i + 1][j] > dp[i][j - 1]) {
                dp[i][j] = dp[i + 1][j];
                path[i][j] = 'd';
            } else {
                dp[i][j] = dp[i][j - 1];
                path[i][j] = 'l';
            }
        }
    }

    StringBuilder result = new StringBuilder();
    int i = 0, j = n - 1;
    while (i <= j) {
        if (path[i][j] == 'd') {
            result.append(s.charAt(i));
            i++;
            j--;
        } else if (path[i][j] == 'l') {
            j--;
        } else {
            i++;
        }
    }
    return result.toString();
}
```

