        int factorial = 1;
        for (int i = 1; i < nums.size(); i++) {
            factorial *= i;
        }

        int index = k / factorial;
        result += std::to_string(nums[index]);
        nums.erase(nums.begin() + index);

        k %= factorial;
    }

    for (int num : nums) {
        result += std::to_string(num);
    }

    return result;
}
