import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> dict = new HashSet<>(wordList);
        if (!dict.contains(endWord)) return Collections.emptyList();

        Map<String, List<String>> neighbors = new HashMap<>();
        Map<String, Integer> distances = new HashMap<>();
        distances.put(beginWord, 0);

        // Build the graph
        buildGraph(beginWord, endWord, dict, neighbors, distances);

        // Find all paths
        List<List<String>> result = new ArrayList<>();
        List<String> path = new ArrayList<>();
        path.add(beginWord);
        findPaths(beginWord, endWord, neighbors, distances, path, result);

        return result;
    }

    private void buildGraph(String beginWord, String endWord, Set<String> dict, Map<String, List<String>> neighbors, Map<String, Integer> distances) {
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        while (!queue.isEmpty()) {
            String currentWord = queue.poll();
            for (String neighbor : getNeighbors(currentWord, dict)) {
                neighbors.computeIfAbsent(currentWord, k -> new ArrayList<>()).add(neighbor);
                if (!distances.containsKey(neighbor)) {
                    distances.put(neighbor, distances.get(currentWord) + 1);
                    queue.offer(neighbor);
                }
            }
        }
    }

    private List<String> getNeighbors(String word, Set<String> dict) {
        List<String> neighbors = new ArrayList<>();
        char[] charArray = word.toCharArray();
        for (int i = 0; i < charArray.length; ++i) {
            char originalChar = charArray[i];
            for (char c = 'a'; c <= 'z'; ++c) {
                charArray[i] = c;
                String newWord = new String(charArray);
                if (dict.contains(newWord) && !newWord.equals(word)) {
                    neighbors.add(newWord);
                }
            }
            charArray[i] = originalChar;
        }
        return neighbors;
    }

    private void findPaths(String currentWord, String endWord, Map<String, List<String>> neighbors, Map<String, Integer> distances, List<String> path, List<List<String>> result) {
        if (currentWord.equals(endWord)) {
            result.add(new ArrayList<>(path));
            return;
        }

        for (String neighbor : neighbors.getOrDefault(currentWord, Collections.emptyList())) {
            if (distances.get(neighbor) == distances.get(currentWord) + 1) {
                path.add(neighbor);
                findPaths(neighbor, endWord, neighbors, distances, path, result);
                path.remove(path.size() - 1);
            }
        }
    }
}
