from collections import deque

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        q = deque([beginWord])
        visited = set([beginWord])
        depth = 0

        while q:
            levelSize = len(q)
            for _ in range(levelSize):
                current = q.popleft()
                if current == endWord:
                    return depth + 1

                for word in wordList:
                    if word not in visited:
                        diff = sum(1 for j in range(len(word)) if current[j] != word[j])
                        if diff == 1:
                            q.append(word)
                            visited.add(word)
            depth += 1
        return 0
