def maxAreaOfIsland(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def bfs(r, c):
        q = deque()
        q.append((r, c))
        visited.add((r, c))
        area = 1

        while q:
            row, col = q.popleft()

            for dr, dc in directions:
                r, c = row + dr, col + dc

                if (
                    r in range(rows)
                    and c in range(cols)
                    and grid[r][c] == "1 "
                    and (r, c) not in visited
                ):
                    q.append((r, c))
                    visited.add((r, c))
                    area += 1

        return area

    max_area = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1 " and (r, c) not in visited:
                max_area = max(max_area, bfs(r, c))

    return max_area
