class Solution {
public:
    vector<int> closestKValues(TreeNode* root, double target, int k) {
        vector<int> result;
        stack<TreeNode*> leftStack, rightStack;

        // Initialize stacks for left and right subtrees
        TreeNode* current = root;
        while (current != nullptr) {
            leftStack.push(current);
            current = current->left;
        }

        current = root;
        while (current != nullptr) {
            rightStack.push(current);
            current = current->right;
        }

        // Find the closest k values
        while (k > 0) {
            int leftVal = INT_MAX, rightVal = INT_MAX;

            if (!leftStack.empty()) {
                leftVal = leftStack.top()->val;
            }

            if (!rightStack.empty()) {
                rightVal = rightStack.top()->val;
            }

            if (abs(target - leftVal) <= abs(target - rightVal)) {
                result.push_back(leftVal);
                leftStack.pop();
                current = leftStack.top()->right;
                while (current != nullptr) {
                    leftStack.push(current);
                    current = current->left;
                }
            } else {
                result.push_back(rightVal);
                rightStack.pop();
                current = rightStack.top()->left;
                while (current != nullptr) {
                    rightStack.push(current);
                    current = current->right;
                }
            }

            k--;
        }

        return result;
    }
};
