public class Solution {
    public List<String> addOperators(String num, int target) {
        List<String> res = new ArrayList<>();
        if (num == null || num.length() == 0) return res;
        helper(res, "", num, target, 0, 0);
        return res;
    }

    private void helper(List<String> res, String path, String num, int target, long pre, long cur) {
        if (num.length() == 0 && cur == target) {
            res.add(path);
            return;
        }
        for (int i = 1; i <= num.length(); i++) {
            String s = num.substring(0, i);
            if (s.length() > 1 && s.charAt(0) == '0') break;
            long n = Long.parseLong(s);
            if (path.length() == 0) {
                helper(res, s, num.substring(i), target, n, n);
            } else {
                helper(res, path + "+" + s, num.substring(i), target, n, cur + n);
                helper(res, path + "-" + s, num.substring(i), target, -n, cur - n);
                helper(res, path + "*" + s, num.substring(i), target, pre * n, cur - pre + pre * n);
            }
        }
    }
}
