import java.util.List;

public class Solution {
    public int[] countSmaller(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }

        mergeSort(nums, indices, result, 0, n - 1);
        return result;
    }

    private void mergeSort(int[] nums, Integer[] indices, int[] result, int left, int right) {
        if (left >= right) {
            return;
        }

        int mid = (left + right) / 2;
        mergeSort(nums, indices, result, left, mid);
        mergeSort(nums, indices, result, mid + 1, right);
        merge(nums, indices, result, left, mid, right);
    }

    private void merge(int[] nums, Integer[] indices, int[] result, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];
        int i = left, j = mid + 1, k = 0;
        int count = 0;

        while (i <= mid && j <= right) {
            if (nums[indices[i]] > nums[indices[j]]) {
                temp[k++] = indices[j++];
                count++;
            } else {
                result[indices[i]] += count;
                temp[k++] = indices[i++];
            }
        }

        while (i <= mid) {
            result[indices[i]] += count;
            temp[k++] = indices[i++];
        }

        while (j <= right) {
            temp[k++] = indices[j++];
        }

        System.arraycopy(temp, 0, indices, left, right - left + 1);
    }
}
