import heapq

class Solution:
    def kthSmallest(self, matrix: List[List[int]], k: int) -> int:
        minHeap = []

        for i in range(min(k, len(matrix))):
            minHeap.append((matrix[i][0], i, 0))

        heapq.heapify(minHeap)

        while k > 1:
            _, i, j = heapq.heappop(minHeap)

            if j + 1 < len(matrix[i]):
