def flatten(head: Node) -> Node:
    if not head:
        return None

    curr = head
    while curr:
        if curr.child:
            insert = curr.child
            next_node = curr.next

            insert.prev = curr
            curr.next = insert
            curr.child = None

            while insert.next:
                insert = insert.next

            if next_node:
                next_node.prev = insert
                insert.next = next_node

