from collections import deque

def sequenceReconstruction(nums, sequences):
    n = len(nums)
    in_degree = [0] * (n + 1)
    adj_list = [[] for _ in range(n + 1)]

    for seq in sequences:
        for i in range(len(seq) - 1):
            adj_list[seq[i]].append(seq[i + 1])
            in_degree[seq[i + 1]] += 1

    q = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    order = []

    while q:
        if len(q) > 1:
            return False
        curr = q.popleft()
        order.append(curr)
        for next in adj_list[curr]:
            in_degree[next] -= 1
            if in_degree[next] == 0:
                q.append(next)

    return order == nums
