    for (int i = 0; i < grid.size(); i++) {
        for (int j = 0; j < grid[0].size(); j++) {
            if (grid[i][j] == 1) {
                queue<pair<int, int>> q;
                q.push({i, j});
                int area = 0;
                while (!q.empty()) {
                    pair<int, int> p = q.front();
                    q.pop();
                    if (p.first < 0 || p.first >= grid.size() || p.second < 0 || p.second >= grid[0].size() || grid[p.first][p.second] == 0) continue;
