class Solution {
    public String decodeString(String s) {
        // Initialize stacks to store counts and results
        Stack<Integer> counts = new Stack<>();
        Stack<String> results = new Stack<>();
        String current = "";
        int ptr = 0;

        // Iterate through the string
        while (ptr < s.length()) {
            // If the character is a digit, parse the count
            if (Character.isDigit(s.charAt(ptr))) {
                int count = 0;
                while (Character.isDigit(s.charAt(ptr))) {
                    count = count * 10 + (s.charAt(ptr) - '0');
                    ptr++;
                }
                counts.push(count);
            } 
            // If the character is '[', push the current result onto the stack
            else if (s.charAt(ptr) == '[') {
                results.push(current);
                current = "";
                ptr++;
            } 
            // If the character is ']', pop the count and repeat the current result
            else if (s.charAt(ptr) == ']') {
                String prev = results.pop();
                int count = counts.pop();
                for (int i = 0; i < count; i++) {
                    prev += current;
                }
                current = prev;
                ptr++;
            } 
            // Otherwise, append the character to the current result
            else {
                current += s.charAt(ptr);
                ptr++;
            }
        }

        // Return the final result
        return current;
    }
}
