                    return memo[s]

                res = []
                if s in dict:
                    res.append(s)

                for i in range(1, len(s)):
                    prefix = s[:i]
                    if prefix not in dict:
                        continue
                    suffix = s[i:]
                    temp = helper(suffix, dict, memo)
                    for t in temp:
                        res.append(prefix + " " + t)

                memo[s] = res
                return res

            word_set = set(word_dict)
            memo = {}
            return helper(s, word_set, memo)

        res = []
        for w in words:
            if word_break(w, words):
                res.append(w)
        return res
