def subarraySum(nums, k):
    prefix_sum_frequency = {0: 1}
    prefix_sum, result = 0, 0

    for num in nums:
        prefix_sum += num
        result += prefix_sum_frequency.get(prefix_sum - k, 0)
        prefix_sum_frequency[prefix_sum] = prefix_sum_frequency.get(prefix_sum, 0) + 1

    return result

def can_partition(nums, k):
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    nums.sort(reverse=True)

    def backtrack(start, current_sum, count):
        if count == k - 1:
            return True

        for i in range(start, len(nums)):
            if current_sum + nums[i] <= target:
                nums[i], nums[start] = nums[start], nums[i]
                if backtrack(start + 1, current_sum + nums[i], count):
                    return True
                nums[i], nums[start] = nums[start], nums[i]

        return False

    return backtrack(0, 0, 0)

