public class Solution {
    public List<Integer> constructDistancedSequence(int n) {
        int[] res = new int[2*n-1];
        res[0] = 1;
        res[2*n-2] = n;
        boolean[] visited = new boolean[n+1];
        visited[1] = true;
        visited[n] = true;
        helper(res, 1, visited, n);
        List<Integer> list = new ArrayList<>();
        for (int num : res) {
            list.add(num);
        }
        return list;
    }

    private boolean helper(int[] res, int idx, boolean[] visited, int n) {
        if (idx == res.length) {
            return true;
        }

        if (res[idx] != 0) {
            return helper(res, idx+1, visited, n);
        }

        for (int i=n; i>=1; i--) {
            if (visited[i]) {
                continue;
