class Solution(object):
    def accountsMerge(self, accounts):
        """
        :type accounts: List[List[str]]
        :rtype: List[List[str]]
        """
        graph = defaultdict(list)
        visited = set()
        res = []

        for account in accounts:
            for i in range(2, len(account)):
                graph[account[i]].append(account[i-1])
                graph[account[i-1]].append(account[i])

        for account in accounts:
            emails = []
            self.dfs(graph, account[1], visited, emails)
            if emails:
                res.append([account[0]] + sorted(emails))
        return res

    def dfs(self, graph, email, visited, emails):
        if email in visited:
            return
        visited.add(email)
        emails.append(email)
        for nei in graph[email]:
            self.dfs(graph, nei, visited, emails)
