std::vector<int> addToArrayForm(std::vector<int>& A, int K) {
    std::vector<int> result;
    int carry = 0;

    // Iterate over the input array from right to left
    for (int i = A.size() - 1; i >= 0 || K > 0 || carry > 0; i--) {
        int digitA = (i >= 0) ? A[i] : 0;
        int digitK = (K > 0) ? K % 10 : 0;
